import React, { useState, useEffect, useRef, useMemo } from "react";
import ReactDOM from "react-dom";

// ─── ERROR BOUNDARY ───────────────────────────────────────────────────────────
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(e) { return { error: e }; }
  componentDidCatch(e, info) { console.error("CRASH:", e, info); }
  render() {
    if (this.state.error) {
      return (
        <div style={{ padding:32, color:"#DC2626", fontFamily:"monospace", fontSize:13, background:"#1A1A1A", minHeight:"100vh" }}>
          <div style={{ fontSize:18, fontWeight:700, marginBottom:16 }}>💥 Something crashed</div>
          <div style={{ marginBottom:8 }}>{this.state.error?.message}</div>
          <pre style={{ fontSize:11, color:"#fbbf24", whiteSpace:"pre-wrap" }}>{this.state.error?.stack?.slice(0,600)}</pre>
          <button onClick={()=>this.setState({error:null})} style={{ marginTop:16, padding:"8px 16px", background:"#f59e0b", border:"none", borderRadius:6, cursor:"pointer", fontWeight:700 }}>Try to recover</button>
        </div>
      );
    }
    return this.props.children;
  }
}


