// ─── PERMISSION HELPER ────────────────────────────────────────────────────────
// Centralised — add new permissions here, use canDo(user, "action") everywhere
function canDo(user, action) {
  const role = user?.role || "viewer";
  const P = {
    // full edit everywhere
    admin:  ["edit_atdp","edit_unmute","edit_originals","edit_settings","sync_rsvp","mark_attendance","view_all"],
    // editor: same as admin minus settings
    editor: ["edit_atdp","edit_unmute","edit_originals","sync_rsvp","mark_attendance","view_all"],
    // JD: edit ATDP + unMute, originals view-only, no settings
    jd:     ["edit_atdp","edit_unmute","sync_rsvp","mark_attendance","view_all"],
    // Ops: RSVP sync + attendance only, everything else read-only
    ops:    ["sync_rsvp","mark_attendance","view_all"],
    // Viewer: read-only
    viewer: ["view_all"],
  };
  return (P[role] || P.viewer).includes(action);
}

