// ─── PRIMITIVE COMPONENTS ─────────────────────────────────────────────────────

function Chip({ status, label }) {
  const s = STATUS[status] || { c:"rgba(124,58,237,0.35)", l: status || "—" };
  return (
    <span style={{ background:s.c+"18", color:s.c, border:`1px solid ${s.c}30`,
      borderRadius:4, padding:"2px 8px", fontSize:10, fontWeight:700,
      letterSpacing:"0.05em", textTransform:"uppercase", whiteSpace:"nowrap" }}>
      {label || s.l}
    </span>
  );
}

function Bar({ val, max, color="#6D28D9", h=5 }) {
  const pct = Math.min((val/(max||1))*100, 100);
  return (
    <div style={{ background:"#E5E7EB", borderRadius:99, height:h, overflow:"hidden", flex:1 }}>
      <div style={{ width:`${pct}%`, height:"100%", background:color, borderRadius:99, transition:"width 0.7s ease" }} />
    </div>
  );
}

function KPI({ val, label, sub, color=C.pink, icon, trend }) {
  const glow = color==="#9D174D"?`linear-gradient(135deg,#EC4899,#DB2777)`:color==="#7C3AED"?`linear-gradient(135deg,#7C3AED,#5B21B6)`:color==="#1E40AF"?`linear-gradient(135deg,#0EA5E9,#0284C7)`:color==="#047857"?`linear-gradient(135deg,#10B981,#059669)`:color==="#C2410C"?`linear-gradient(135deg,#F97316,#EA580C)`:color==="#B45309"?`linear-gradient(135deg,#F59E0B,#D97706)`:color==="#6D28D9"?`linear-gradient(135deg,#8B5CF6,#7C3AED)`:color==="#DC2626"?`linear-gradient(135deg,#EF4444,#DC2626)`:color?`linear-gradient(135deg,${color},${color})`:"linear-gradient(135deg,#7C3AED,#5B21B6)";
  return (
    <div className="kpi-shimmer" style={{ background:"#fff", border:"1px solid #EBEBEB", borderRadius:12, padding:"14px 16px", position:"relative", overflow:"hidden", color:"#1A1A1A", boxShadow:"0 1px 2px rgba(0,0,0,0.04)" }}>
      <div style={{ position:"absolute", top:0, left:0, right:0, height:3, background:color, opacity:0.9 }} />
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
        <div>
          <div style={{ fontSize:10, fontWeight:600, color:"#9CA3AF", textTransform:"uppercase", letterSpacing:"0.08em", marginBottom:6 }}>{label}</div>
          <div style={{ fontFamily:"'Playfair Display',serif", fontSize:32, fontWeight:800, color, lineHeight:1, letterSpacing:"-0.03em" }}>{val}</div>
          {sub && <div style={{ fontSize:11, color:"#6B7280", marginTop:6, lineHeight:1.4 }}>{sub}</div>}
        </div>
        {icon && <div style={{ fontSize:22, opacity:0.4 }}>{icon}</div>}
      </div>
      {trend !== undefined && (
        <div style={{ marginTop:10, display:"flex", alignItems:"center", gap:4 }}>
          <span style={{ fontSize:11, fontWeight:700, color:trend>=0?C.green:C.red }}>{trend>=0?"↑":"↓"}{Math.abs(trend)}%</span>
          <span style={{ fontSize:10, color:"#6B7280" }}>vs last period</span>
        </div>
      )}
    </div>
  );
}

function Field({ label, value, onChange, type="text", placeholder, options, disabled, textarea, rows=3 }) {
  const base = { background:"#fff", border:"1px solid #E5E7EB", borderRadius:8, padding:"8px 12px", color:"#1A1A1A", fontSize:13, fontFamily:"inherit", outline:"none", width:"100%", opacity:disabled?0.5:1 };
  return (
    <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
      {label && <label style={{ fontSize:10, fontWeight:700, color:"#6B7280", textTransform:"uppercase", letterSpacing:"0.08em" }}>{label}</label>}
      {options
        ? <select value={value||""} onChange={e=>onChange(e.target.value)} disabled={disabled} style={{...base, background:"#fff"}}>
            {options.map(o=><option key={o} value={o}>{o||"—"}</option>)}
          </select>
        : textarea
          ? <textarea value={value||""} onChange={e=>onChange(e.target.value)} placeholder={placeholder} rows={rows} style={{...base, resize:"vertical"}} />
          : <input type={type} value={value||""} onChange={e=>onChange(e.target.value)} placeholder={placeholder} disabled={disabled} style={base} />
      }
    </div>
  );
}

function Btn({ children, onClick, v="primary", sm, full }) {
  const V = { primary:{bg:"linear-gradient(135deg,#7C3AED,#5B21B6)",tc:"#fff"}, secondary:{bg:"#F9FAFB",tc:"#374151",border:"1px solid #E5E7EB"}, danger:{bg:"rgba(220,38,38,0.08)",tc:"#DC2626",border:"1px solid rgba(239,68,68,0.25)"}, ghost:{bg:"transparent",tc:"#6B7280",border:"1px solid #E5E7EB"}, success:{bg:"rgba(4,120,87,0.08)",tc:"#047857",border:"1px solid rgba(4,120,87,0.25)"} };
  const s = V[v]||V.primary;
  return (
    <button onClick={onClick} style={{ background:s.bg, border:s.border||"none", borderRadius:8, color:s.tc, padding:sm?"5px 10px":"9px 18px", fontSize:sm?11:13, fontWeight:700, cursor:"pointer", fontFamily:"inherit", width:full?"100%":"auto", letterSpacing:"0.02em", whiteSpace:"nowrap", flexShrink:0 }}>
      {children}
    </button>
  );
}

function Modal({ title, onClose, children, wide, ultrawide }) {
  useEffect(()=>{
    // Lock both body and the main scroll container
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const mainContent = document.querySelector(".main-content");
    const prevMain = mainContent ? mainContent.style.overflow : "";
    if (mainContent) mainContent.style.overflow = "hidden";
    return ()=>{
      document.body.style.overflow = prev;
      if (mainContent) mainContent.style.overflow = prevMain;
    };
  }, []);
  return ReactDOM.createPortal(
    <div style={{ position:"fixed", inset:0,
      background:"rgba(0,0,0,0.55)",
      backdropFilter:"blur(16px)", WebkitBackdropFilter:"blur(16px)",
      zIndex:9999, display:"flex", alignItems:"center", justifyContent:"center", padding:16,
      animation:"fadeIn 0.16s ease" }}
      onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{
        background:"#fff",
        backdropFilter:"blur(40px)", WebkitBackdropFilter:"blur(40px)",
        border:"1px solid rgba(124,58,237,0.1)",
        borderRadius:22, padding:28,
        width:"100%", maxWidth:ultrawide?1100:wide?820:560,
        maxHeight:"90vh", overflowY:"auto",
        boxShadow:"0 40px 120px rgba(0,0,0,0.9), 0 0 0 1px rgba(0,0,0,0.03), inset 0 1px 0 rgba(124,58,237,0.06)",
        animation:"fadeSlideUp 0.22s cubic-bezier(0.34,1.56,0.64,1)",
        fontFamily:"'DM Sans',sans-serif",
      }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:22 }}>
          <div style={{ fontSize:16, fontWeight:800, color:"#1A1A1A" }}>{title}</div>
          <button onClick={onClose} style={{ background:"#F3F4F6", border:"1px solid #E5E7EB", borderRadius:8, color:"#6B7280", fontSize:14, cursor:"pointer", fontFamily:"inherit", padding:"4px 8px" }}>✕</button>
        </div>
        {children}
      </div>
    </div>,
    document.body
  );
}

