// ─── EXPORT CSV ───────────────────────────────────────────────────────────────
function exportCSV(rows, filename) {
  if (!rows?.length) return;
  const flat = rows.map(r => {
    const out = {};
    for (const [k,v] of Object.entries(r)) { out[k] = typeof v==="object"&&v!==null ? JSON.stringify(v) : v; }
    return out;
  });
  const headers = Object.keys(flat[0]);
  const csv = [headers.join(","), ...flat.map(r=>headers.map(h=>`"${String(r[h]??"").replace(/"/g,'""')}"`).join(","))].join("\n");
  const a = document.createElement("a"); a.href="data:text/csv;charset=utf-8,"+encodeURIComponent(csv); a.download=filename; a.click();
}

// ─── PERIOD FILTER HELPER ─────────────────────────────────────────────────────
function sessionMatchesPeriod(session, period) {
  if (period === "all") return true;
  const d = session.date || "";
  if (!d) return false;
  const mon = d.split(" ")[0]?.toLowerCase();
  const yr  = d.split(" ")[1];
  const Q1 = ["jan","feb","mar"], Q2 = ["apr","may","jun"], Q3 = ["jul","aug","sep"], Q4 = ["oct","nov","dec"];
  const now = new Date();
  const nowMon = now.toLocaleString("en",{month:"short"}).toLowerCase();
  const nowYr  = String(now.getFullYear());
  const prevDate = new Date(now.getFullYear(), now.getMonth()-1, 1);
  const prevMon = prevDate.toLocaleString("en",{month:"short"}).toLowerCase();
  const prevYr  = String(prevDate.getFullYear());
  if (period==="month") return mon===nowMon && yr===nowYr;
  if (period==="prev")  return mon===prevMon && yr===prevYr;
  if (period==="q1")    return Q1.includes(mon);
  if (period==="q2")    return Q2.includes(mon);
  if (period==="q3")    return Q3.includes(mon);
  if (period==="q4")    return Q4.includes(mon);
  if (period==="2025")  return yr==="2025";
  if (period==="2026")  return yr==="2026";
  return true;
}

// ─── COLUMN MANAGER ──────────────────────────────────────────────────────────
function ColumnManager({ customFields, onAdd, onDelete, onRename, onMove, onClose }) {
  const [newName, setNewName] = useState("");
  const [editingIdx, setEditingIdx] = useState(null);
  const [editingVal, setEditingVal] = useState("");
  const [dragIdx, setDragIdx] = useState(null);
  const [dragOverIdx, setDragOverIdx] = useState(null);

  function commitRename(i) {
    if (editingVal.trim()) onRename(customFields[i], editingVal.trim());
    setEditingIdx(null); setEditingVal("");
  }

  function handleDrop(toIdx) {
    if (dragIdx !== null && dragIdx !== toIdx) onMove(dragIdx, toIdx);
    setDragIdx(null); setDragOverIdx(null);
  }

  const FIXED = ["Name","Stream","Age","Gender","City","Joined","Contract","Status","Teacher","Phone","Email","Parent","Notes"];

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:18 }}>

      {/* Fixed columns (read-only info) */}
      <div>
        <div style={{ fontSize:10, fontWeight:700, color:"#6B7280", textTransform:"uppercase", letterSpacing:"0.08em", marginBottom:8 }}>
          Built-in Columns (always visible, cannot be removed)
        </div>
        <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
          {FIXED.map(f=>(
            <span key={f} style={{ fontSize:11, background:"#F9FAFB", border:"1px solid #E5E7EB", borderRadius:6, padding:"3px 10px", color:"#6B7280" }}>{f}</span>
          ))}
        </div>
      </div>

      <div style={{ height:1, background:"#E5E7EB" }} />

      {/* Custom columns */}
      <div>
        <div style={{ fontSize:10, fontWeight:700, color:"#6B7280", textTransform:"uppercase", letterSpacing:"0.08em", marginBottom:10 }}>
          Custom Columns — drag to reorder, click to rename
        </div>
        {customFields.length === 0 && (
          <div style={{ fontSize:12, color:"#6B7280", padding:"12px 0" }}>No custom columns yet. Add one below.</div>
        )}
        <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
          {customFields.map((cf, i) => (
            <div
              key={cf}
              draggable
              onDragStart={()=>setDragIdx(i)}
              onDragOver={e=>{ e.preventDefault(); setDragOverIdx(i); }}
              onDragEnd={()=>{ setDragIdx(null); setDragOverIdx(null); }}
              onDrop={()=>handleDrop(i)}
              style={{
                display:"flex", alignItems:"center", gap:10, padding:"9px 12px",
                background: dragOverIdx===i ? "rgba(4,120,87,0.1)" : "#F9FAFB",
                border:`1px solid ${dragOverIdx===i ? "#047857" : "#E5E7EB"}`,
                borderRadius:8, cursor:"grab", transition:"all 0.1s"
              }}
            >
              {/* Drag handle */}
              <span style={{ color:"#6B7280", fontSize:14, cursor:"grab", flexShrink:0 }}>⠿</span>
              <span style={{ fontSize:11, color:"#6B7280", width:18, flexShrink:0 }}>#{i+1}</span>

              {/* Name / edit */}
              {editingIdx === i ? (
                <input
                  autoFocus
                  value={editingVal}
                  onChange={e=>setEditingVal(e.target.value)}
                  onKeyDown={e=>{ if(e.key==="Enter") commitRename(i); if(e.key==="Escape"){setEditingIdx(null);setEditingVal("");} }}
                  onBlur={()=>commitRename(i)}
                  style={{ flex:1, background:"#F9FAFB", border:"1px solid #0EA5E9", borderRadius:6, padding:"4px 8px", color:"#1A1A1A", fontFamily:"inherit", fontSize:13, outline:"none" }}
                />
              ) : (
                <span
                  onClick={()=>{ setEditingIdx(i); setEditingVal(cf); }}
                  style={{ flex:1, fontSize:13, fontWeight:600, color:"#1E40AF", cursor:"text" }}
                  title="Click to rename"
                >{cf}</span>
              )}

              {/* Move up/down */}
              <button onClick={()=>i>0&&onMove(i,i-1)} disabled={i===0}
                style={{ background:"none", border:"none", color:i===0?"#E5E7EB":"#6B7280", cursor:i===0?"default":"pointer", fontSize:13, padding:"2px 4px", flexShrink:0 }}>↑</button>
              <button onClick={()=>i<customFields.length-1&&onMove(i,i+1)} disabled={i===customFields.length-1}
                style={{ background:"none", border:"none", color:i===customFields.length-1?"#E5E7EB":"#6B7280", cursor:i===customFields.length-1?"default":"pointer", fontSize:13, padding:"2px 4px", flexShrink:0 }}>↓</button>

              {/* Delete */}
              <button onClick={()=>onDelete(cf)}
                style={{ background:"rgba(201,123,90,0.1)", border:`1px solid ${C.red}30`, borderRadius:6, color:C.red, cursor:"pointer", fontSize:11, padding:"3px 8px", fontFamily:"inherit", fontWeight:700, flexShrink:0 }}>
                Remove
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* Add new column */}
      <div style={{ background:"rgba(4,120,87,0.05)", border:"1px dashed rgba(4,120,87,0.4)", borderRadius:10, padding:14 }}>
        <div style={{ fontSize:11, fontWeight:700, color:"#6B7280", textTransform:"uppercase", letterSpacing:"0.08em", marginBottom:10 }}>Add New Column</div>
        <div style={{ display:"flex", gap:8 }}>
          <input
            value={newName}
            onChange={e=>setNewName(e.target.value)}
            onKeyDown={e=>{ if(e.key==="Enter"&&newName.trim()){onAdd(newName);setNewName("");} }}
            placeholder='e.g. "Instagram Handle" or "Superstar Result"'
            style={{ flex:1, background:"#F9FAFB", border:"1px solid #E5E7EB", borderRadius:8, padding:"9px 12px", color:"#1A1A1A", fontSize:13, fontFamily:"inherit", outline:"none" }}
          />
          <button
            onClick={()=>{ if(newName.trim()){onAdd(newName);setNewName("");} }}
            disabled={!newName.trim() || customFields.includes(newName.trim())}
            style={{ background:"linear-gradient(135deg,#7C3AED,#5B21B6)", border:"none", borderRadius:8, color:"#fff", padding:"9px 18px", fontSize:13, fontWeight:700, cursor:"pointer", fontFamily:"inherit", opacity:(!newName.trim()||customFields.includes(newName.trim()))?0.4:1 }}
          >Add</button>
        </div>
        {customFields.includes(newName.trim()) && newName.trim() && (
          <div style={{ fontSize:11, color:C.red, marginTop:6 }}>A column with that name already exists.</div>
        )}
      </div>

      <div style={{ display:"flex", justifyContent:"flex-end" }}>
        <button onClick={onClose} style={{ background:"#F9FAFB", border:"1px solid #E5E7EB", borderRadius:8, color:"#374151", padding:"9px 20px", fontSize:13, fontWeight:700, cursor:"pointer", fontFamily:"inherit" }}>Done</button>
      </div>
    </div>
  );
}

// ─── ATDP SECTION ─────────────────────────────────────────────────────────────
function ATDPSection({ data, canEdit, canMarkAtt, onUpdate, period, anthropicKey, fullData, onMarkAttendance }) {
  const [tab, setTab] = useState("Students");
  const [atdpMainTab, setAtdpMainTab] = useState("students");
  const [modal, setModal] = useState(null);
  const [profileStudent, setProfileStudent] = useState(null);
  const { ask:confirmDelete, ConfirmModal:DeleteConfirmModal } = useConfirmDelete();
  const [showImporter, setShowImporter] = useState(false);
  const [showRsvpImporter, setShowRsvpImporter] = useState(false);
  const rsvpData = data.rsvpHistory || data.rsvpSessions || [];
  const [expandedLane, setExpandedLane] = useState(null);
  const [sessionModal, setSessionModal] = useState(null);
  const [unverifiedOpen, setUnverifiedOpen] = useState(true);
  const [dismissedMatches, setDismissedMatches] = useState(()=>{
    try{ return JSON.parse(localStorage.getItem("artium-dismissed-matches")||"{}"); }catch{return{};}
  });
  const [resolvedRsvps, setResolvedRsvps] = useState(()=>{
    try{ return JSON.parse(localStorage.getItem("artium-resolved-rsvps")||"{}"); }catch{return{};}
  });
  const [markAttSession, setMarkAttSession] = useState(null); // session object to mark attendance for


  const [studentQ, setStudentQ] = useState("");
  const [studentSort, setStudentSort] = useState("name-asc");
  const [showColFilter, setShowColFilter] = useState(false);
  const [hiddenCols, setHiddenCols] = useState([]);
  const students = data.students || [];
  const filtStudents = (() => {
    const base = studentQ.length<2
      ? [...students]
      : students.filter(s=>
          `${s.name} ${s.stream} ${s.city} ${s.teacher} ${s.notes} ${s.phone||""}`.toLowerCase().includes(studentQ.toLowerCase()) ||
          (s.phone && String(s.phone).includes(studentQ.trim()))
        );
    const [field, dir] = studentSort.split("-");
    // Pre-compute signed set once (not inside comparator)
    const signedSet = new Set(base.filter(s=>(s.notes||"").includes("Contract signed")).map(s=>s.id));
    return base.sort((a,b) => {
      if (field === "engagement") {
        const as = computeEngagementScore(a, data).total;
        const bs = computeEngagementScore(b, data).total;
        return dir === "asc" ? as - bs : bs - as;
      }
      let av = a[field]||"", bv = b[field]||"";
      if (field==="contract") { av = signedSet.has(a.id)?1:0; bv = signedSet.has(b.id)?1:0; }
      if (typeof av==="number") return dir==="asc"?av-bv:bv-av;
      return dir==="asc"?String(av).localeCompare(String(bv)):String(bv).localeCompare(String(av));
    });
  })();
  const lanes    = data.groomingLanes || [];
  const ws       = data.workshops || [];
  const customFields = data.customFields || [];

  // helpers
  const open = (type, form, idx) => setModal({ type, form, idx:idx??null });
  const close = () => setModal(null);
  const save = (key, arr) => { onUpdate({...data, [key]:arr}); close(); };

  // students
  const newStudent = () => ({ id:`s${Date.now()}`, name:"", gender:"", stream:"PFM Hindi", age:"", city:"", joined:"", contract:false, status:"active", teacher:"", phone:"", email:"", parentName:"", parentPhone:"", notes:"", custom:{} });
  const saveStudent = f => { const arr=[...students]; if(modal.idx!==null){ const realIdx=arr.findIndex(s=>s.id===f.id); if(realIdx>=0) arr[realIdx]=f; else arr[modal.idx]=f; } else arr.push({...f,id:`s${Date.now()}`}); save("students",arr); };
  const delStudent  = i => save("students", students.filter((_,x)=>x!==i));
  const delStudentById = id => save("students", students.filter(s=>s.id!==id));

  // lanes
  const saveLane = f => { const arr=[...lanes]; if(modal.idx!==null) arr[modal.idx]=f; else arr.push({...f,id:`gl${Date.now()}`,sessions:makeLaneSessions("jd")}); save("groomingLanes",arr); };
  const delLane  = i => save("groomingLanes", lanes.filter((_,x)=>x!==i));

  // sessions within a lane
  const saveSession = (laneIdx, f) => {
    const arr = lanes.map((l,i) => {
      if (i!==laneIdx) return l;
      const sessions = [...l.sessions]; sessions[sessionModal.idx]=f;
      return {...l, sessions};
    });
    onUpdate({...data, groomingLanes:arr}); setSessionModal(null);
  };

  // workshops
  const newWs = () => ({ id:`w${Date.now()}`, name:"", mentor:"", date:"", status:"planned", attendees:0, recordingLink:"", notes:"" });
  const saveWs = f => { const arr=[...ws]; if(modal.idx!==null) arr[modal.idx]=f; else arr.push({...f,id:`w${Date.now()}`}); save("workshops",arr); };
  const delWs  = i => save("workshops", ws.filter((_,x)=>x!==i));

  // custom fields — no window.prompt, all inline
  const [showColMgr, setShowColMgr] = useState(false);
  const addCustomField = (name) => {
    if (!name || !name.trim()) return;
    if (customFields.includes(name.trim())) return;
    onUpdate({...data, customFields:[...customFields, name.trim()]});
  };
  const delCustomField = fn => {
    onUpdate({...data, customFields:customFields.filter(f=>f!==fn),
      students:students.map(s=>{ const c={...s.custom}; delete c[fn]; return {...s,custom:c}; })});
  };
  const renameCustomField = (oldName, newName) => {
    if (!newName || !newName.trim() || oldName===newName.trim()) return;
    const updated = customFields.map(f=>f===oldName?newName.trim():f);
    onUpdate({...data, customFields:updated,
      students:students.map(s=>{ const c={...s.custom}; c[newName.trim()]=c[oldName]; delete c[oldName]; return {...s,custom:c}; })});
  };
  const moveCustomField = (from, to) => {
    const arr=[...customFields];
    const [item]=arr.splice(from,1); arr.splice(to,0,item);
    onUpdate({...data, customFields:arr});
  };

  // period filter for sessions
  const filteredSessions = (lane) => period==="all" ? lane.sessions : lane.sessions.filter(s=>sessionMatchesPeriod(s,period));
  const doneInPeriod = lanes.reduce((a,l)=>a+filteredSessions(l).filter(s=>s.status==="done").length,0);

  return (
    <div>
      <SectionHead logo={LOGO_ATP} logoH={60} title="Artium Talent Development Programme"
        sub={`${students.length} students · Invitation-only elite track`}
        action={canEdit && tab==="Students" && (
          <div style={{ display:"flex", gap:8 }}>
            <button onClick={()=>setShowImporter(true)} style={{ background:"rgba(30,64,175,0.12)", border:`1px solid ${C.teal}44`, borderRadius:9, color:C.teal, padding:"8px 16px", fontSize:13, fontWeight:700, cursor:"pointer", fontFamily:"inherit" }}>📥 Import from Sheet</button>
            <Btn onClick={()=>open("student",newStudent())}>+ Add Student</Btn>
          </div>
        )}
      />

      {/* KPIs */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(5,1fr)", gap:12, marginBottom:22 }}>
        <KPI val={students.length} label="Total Students" sub="All cohorts combined" color="#1E40AF" />
        <KPI val={students.filter(s=>s.status==="active").length} label="Active Students" sub={`${Math.round(students.filter(s=>s.status==="active").length/(students.length||1)*100)}% engagement`} color="#047857" />
        <KPI val={doneInPeriod} label={`Sessions Done`} sub={PERIODS.find(p=>p.key===period)?.label || "All time"} color="#047857" />
        <KPI val={`${lanes.filter(l=>l.status==="active").length}/${lanes.length}`} label="Active Lanes" sub="Grooming programme" color="#B45309" />
      </div>

      {/* ATDP Charts Row */}
      {tab==="Students" && (
      <CollapsibleSection title="Cohort Insights" icon="📊" accent="#1E40AF" defaultOpen={false}>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12, marginBottom:4 }}>
          <ChartCard title="Stream Distribution">
            <MiniBarChart
              data={[
                {l:"Film/Pop",  v:students.filter(s=>s.stream==="PFM Hindi").length},
                {l:"Western",   v:students.filter(s=>s.stream==="Western Vocals").length},
                {l:"HC",        v:students.filter(s=>s.stream==="Hindustani Classical").length},
                {l:"Carnatic",  v:students.filter(s=>s.stream==="Carnatic Classical").length},
              ]}
              labelKey="l" valueKey="v" color={C.teal} height={110}
            />
          </ChartCard>
          <ChartCard title="City Distribution">
            <MiniBarChart
              data={[...new Set(students.map(s=>s.city))].filter(Boolean).map(city=>({
                l:city,
                v:students.filter(s=>s.city===city).length
              }))}
              labelKey="l" valueKey="v" color="#1E40AF" height={130}
            />
          </ChartCard>
          <ChartCard title="Status Overview">
            <MiniDonut
              data={[
                {label:"Active",  pct:students.filter(s=>s.status==="active").length},
                {label:"Inactive",pct:students.filter(s=>s.status==="inactive").length},
                {label:"On Hold", pct:students.filter(s=>s.status==="on hold").length},
              ].filter(d=>d.pct>0)}
              colorMap={{Active:C.green,Inactive:C.red,"On Hold":C.gold}}
              size={110}
            />
          </ChartCard>
        </div>
        </CollapsibleSection>
      )}

      <div style={{ display:"flex", gap:2, marginBottom:18, background:"#F0F0F0", borderRadius:12, padding:3, border:"1px solid #E5E7EB" }}>
        {[["students","👥 Students & Grooming"],["attention","📊 Attention Tracker"]].map(([k,l])=>(
          <button key={k} onClick={()=>setAtdpMainTab(k)} style={{ flex:1, padding:"7px 12px", borderRadius:9, border:"none", cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600, background:atdpMainTab===k?"#fff":"transparent", color:atdpMainTab===k?"#1E40AF":"#6B7280", boxShadow:atdpMainTab===k?"0 1px 4px rgba(0,0,0,0.08)":"none", transition:"all 0.18s ease" }}>
            {l}
          </button>
        ))}
      </div>
      {atdpMainTab==="attention" && <AttentionTracker data={data} canEdit={canEdit} onUpdate={onUpdate} anthropicKey={anthropicKey} />}
      {atdpMainTab==="students" && <>
      <SubTabs tabs={["Students","Grooming Lanes","Expert Workshops","Contracts"]} active={tab} onChange={setTab} accent="#1E40AF" />

      {/* ── Students ── */}
      {tab==="Students" && (
        <>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:12 }}>
            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
              <SearchBar q={studentQ} setQ={setStudentQ} placeholder="Search students…" compact />
              <div style={{ fontSize:12, color:"#6B7280" }}>{filtStudents.length}/{students.length}</div>
              <select value={studentSort} onChange={e=>setStudentSort(e.target.value)} style={{ background:"#F9FAFB", border:"1px solid #E5E7EB", borderRadius:7, padding:"5px 10px", color:"#374151", fontSize:11, fontFamily:"inherit", outline:"none" }}>
                <option value="name-asc">Name A→Z</option>
                <option value="name-desc">Name Z→A</option>
                <option value="stream-asc">Stream A→Z</option>
                <option value="city-asc">City A→Z</option>
                <option value="joined-desc">Newest first</option>
                <option value="joined-asc">Oldest first</option>
                <option value="contract-desc">Contract signed first</option>
                <option value="status-asc">Status</option>
                <option value="engagement-desc">Engagement ↓</option>
                <option value="engagement-asc">Engagement ↑</option>
              </select>
            </div>
            <div style={{ display:"flex", gap:8 }}>
              {canEdit && <Btn v="ghost" sm onClick={()=>setShowColMgr(true)}>⚙ Columns</Btn>}
              <div style={{ position:"relative" }}>
                <Btn v="ghost" sm onClick={()=>setShowColFilter(p=>!p)}>🔽 Show/Hide Cols</Btn>
                {showColFilter && (
                  <div style={{ position:"absolute", right:0, top:"110%", background:"#fff", border:"1px solid #E5E7EB", borderRadius:10, padding:"10px 14px", zIndex:999, minWidth:200, display:"flex", flexDirection:"column", gap:6 }}>
                    <div style={{ fontSize:10, fontWeight:700, color:"#6B7280", textTransform:"uppercase", marginBottom:4 }}>Toggle columns</div>
                    {["Stream","Age","Gender","City","Joined","Contract","Status","Teacher","Phone","Email","Parent","Notes"].map(col=>(
                      <label key={col} style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", fontSize:12, color:"#374151" }}>
                        <input type="checkbox" checked={!hiddenCols.includes(col)} onChange={e=>setHiddenCols(p=>e.target.checked?p.filter(c=>c!==col):[...p,col])} />
                        {col}
                      </label>
                    ))}
                    <button onClick={()=>setHiddenCols([])} style={{ marginTop:6, background:"none", border:"1px solid #E5E7EB", borderRadius:6, color:"#6B7280", padding:"4px 10px", fontSize:11, cursor:"pointer", fontFamily:"inherit" }}>Reset</button>
                  </div>
                )}
              </div>
              <Btn v="ghost" sm onClick={()=>exportCSV(filtStudents,"atdp-students.csv")}>⬇ Export CSV</Btn>
            </div>
          </div>
          <div style={{ overflowX:"auto", overflowY:"auto", maxHeight:"60vh", borderRadius:12, border:"1px solid #E5E7EB", boxShadow:"0 1px 3px rgba(0,0,0,0.04)" }}>
            <table style={{ width:"100%", borderCollapse:"collapse", fontSize:12, tableLayout:"auto" }}>
              <thead>
                <tr style={{ borderBottom:"1px solid #E5E7EB", background:"#F9FAFB", position:"sticky", top:0, zIndex:10 }}>
                  {["Name","Engagement","Stream","Age","Gender","City","Joined","Contract","Status","Teacher","Phone","Email","Parent","Notes",...customFields,""].filter(h=>!hiddenCols.includes(h)).map((h,hi)=>(
                    <th key={hi} style={{ textAlign:"left", padding:"9px 12px", fontSize:10, fontWeight:700, color:customFields.includes(h)?"#9D174D":"#9CA3AF", textTransform:"uppercase", letterSpacing:"0.06em", whiteSpace:"nowrap" }}>
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtStudents.map((s,i)=>(
                  <tr key={s.id} style={{ borderBottom:"1px solid #F0F0F0", transition:"background 0.12s", height:46 }} onMouseEnter={e=>e.currentTarget.style.background="#F8FAFC"} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                    <td style={{ padding:"9px 12px" }}><div style={{ display:"flex", alignItems:"center", gap:8 }}><PhotoUploader photoKey={`atdp-student-${s.id}`} size={30} shape="circle" /><span style={{ fontWeight:700, color:"#1A1A1A", whiteSpace:"nowrap" }}>{s.name}</span></div></td>
                    {!hiddenCols.includes("Engagement")&&<td style={{ padding:"9px 12px" }}><EngagementBadge score={computeEngagementScore(s, data)} compact /></td>}
                    {!hiddenCols.includes("Stream")&&<td style={{ padding:"9px 12px", color:"#374151", whiteSpace:"nowrap" }}>
                      {s.streams && s.streams.length > 1
                        ? <span title={s.streams.join(", ")}>{s.streams[0]} <span style={{ fontSize:9, color:"#9CA3AF" }}>+{s.streams.length-1}</span></span>
                        : (s.stream||"—")}
                    </td>}
                    {!hiddenCols.includes("Age")&&<td style={{ padding:"9px 12px", color:"#374151" }}>{s.age}</td>}
                    {!hiddenCols.includes("Gender")&&<td style={{ padding:"9px 12px", color:"#6B7280" }}>{s.gender||"—"}</td>}
                    <td style={{ padding:"9px 12px", color:"#374151" }}>{s.city}</td>
                    <td style={{ padding:"9px 12px", color:"#374151", whiteSpace:"nowrap" }}>{s.joined}</td>
                    <td style={{ padding:"9px 10px" }}>
                      <Chip status={(s.notes||"").includes("Contract signed")?"signed":"pending"} label={(s.notes||"").includes("Contract signed")?"Signed":"Pending"} />
                    </td>
                    <td style={{ padding:"9px 10px" }}><Chip status={s.status} /></td>
                    <td style={{ padding:"9px 12px", color:"#374151" }}>
                      {s.teachers && Object.keys(s.teachers).length > 1
                        ? <span title={Object.entries(s.teachers).map(([stream,t])=>stream+": "+t).join(", ")} style={{ cursor:"help" }}>
                            {Object.values(s.teachers).filter(Boolean)[0]}
                            <span style={{ fontSize:10, color:"#9CA3AF", marginLeft:4 }}>
                              +{Object.values(s.teachers).filter(Boolean).length - 1}
                            </span>
                          </span>
                        : (s.teacher||"—")}
                    </td>
                    <td style={{ padding:"9px 12px", color:"#6B7280" }}>{s.phone||"—"}</td>
                    <td style={{ padding:"9px 12px", color:"#6B7280" }}>{s.email||"—"}</td>
                    <td style={{ padding:"9px 12px", color:"#6B7280", whiteSpace:"nowrap" }}>{s.parentName||"—"}</td>
                    <td style={{ padding:"9px 12px", color:"#6B7280", maxWidth:160, position:"relative" }}>
                      <div title={s.notes||"—"} style={{ overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", maxWidth:150, cursor:s.notes?"help":"default" }}>
                        {s.notes ? (s.notes.length>30 ? s.notes.slice(0,30)+"…" : s.notes) : "—"}
                      </div>
                    </td>
                    {customFields.map(cf=>(
                      <td key={cf} style={{ padding:"9px 12px", color:"#6B7280" }}>{s.custom?.[cf]||"—"}</td>
                    ))}
                    <td style={{ padding:"9px 10px" }}>
                      <div style={{ display:"flex", gap:4, flexWrap:"nowrap" }}>
                        <button onClick={()=>setProfileStudent(s.name)} style={{ background:"rgba(30,64,175,0.08)", border:"1px solid rgba(14,165,233,0.25)", borderRadius:6, color:"#1E40AF", padding:"4px 9px", fontSize:11, fontWeight:700, cursor:"pointer", fontFamily:"inherit", whiteSpace:"nowrap" }}>✦ Profile</button>
                        <WhatsAppButton name={s.name} phone={s.phone||""} reason={!s.contract?"contract is still pending":"checking in on their progress"} type="student" anthropicKey={anthropicKey} />
                        {canEdit && <>
                          <Btn v="ghost" sm onClick={()=>open("student",{...s,custom:{...s.custom}},students.findIndex(st=>st.id===s.id))}>✏️</Btn>
                          <Btn v="danger" sm onClick={()=>confirmDelete(s.name, ()=>delStudentById(s.id))}>🗑</Btn>
                        </>}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {/* ── Grooming Lanes ── */}
      {tab==="Grooming Lanes" && (
        <>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:8, marginBottom:14, flexWrap:"wrap" }}>
            <button onClick={()=>setShowRsvpImporter(true)} style={{ display:"flex", alignItems:"center", gap:6, background:"rgba(4,120,87,0.1)", border:`1px solid rgba(236,72,153,0.3)`, borderRadius:9, color:"#065F46", padding:"7px 14px", fontSize:12, fontWeight:700, cursor:"pointer", fontFamily:"inherit" }}>
              📋 Import RSVPs {rsvpData.length>0&&<span style={{ fontSize:10, background:"rgba(4,120,87,0.2)", borderRadius:4, padding:"1px 6px", marginLeft:4 }}>{rsvpData.reduce((a,s)=>a+s.rsvps.length,0)} RSVPs</span>}
            </button>
            <div style={{ display:"flex", gap:8, alignItems:"center" }}>
              {rsvpData.length>0 && canMarkAtt && (
                <button onClick={()=>onMarkAttendance&&onMarkAttendance()} style={{ display:"flex", alignItems:"center", gap:6, background:"rgba(4,120,87,0.1)", border:"1px solid rgba(110,231,183,0.3)", borderRadius:9, color:C.green, padding:"7px 14px", fontSize:12, fontWeight:700, cursor:"pointer", fontFamily:"inherit" }}>
                  ✅ Mark Attendance
                </button>
              )}
              {canEdit && <Btn sm onClick={()=>open("lane",{name:"",mentor:"",stream:"All Streams",status:"active"})}>+ Add Lane</Btn>}
            </div>
          </div>

          {/* Session Health Dashboard */}
          <SessionHealthDashboard
            rsvpData={rsvpData}
            students={students}
            lanes={lanes}
            data={data}
          />

          {/* RSVP Summary Cards + Unverified Alert */}
          {rsvpData.length > 0 && (
            <RsvpOverviewPanel
              rsvpData={rsvpData}
              students={students}
              data={data}
              onUpdate={onUpdate}
              openStudentForm={(prefilled)=>open("student", prefilled, null)}
              unverifiedOpen={unverifiedOpen}
              setUnverifiedOpen={setUnverifiedOpen}
              dismissedMatches={dismissedMatches}
              setDismissedMatches={setDismissedMatches}
              resolvedRsvps={resolvedRsvps}
              setResolvedRsvps={setResolvedRsvps}
              onMarkAttendance={(session)=>setMarkAttSession(session)}
            />
          )}
                    <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
            {lanes.map((lane,li)=>{
              const sessions = filteredSessions(lane);
              const done = lane.sessions.filter(s=>s.status==="done").length;
              const isOpen = expandedLane===lane.id;
              return (
                <div key={lane.id} style={{ background:"#fff", border:`1px solid ${isOpen?"rgba(4,120,87,0.4)":"#E5E7EB"}`, borderRadius:12, overflow:"hidden" }}>
                  {/* Lane header */}
                  <div onClick={()=>setExpandedLane(isOpen?null:lane.id)} style={{ padding:"16px 18px", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                    <div style={{ flex:1 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:8 }}>
                        <div style={{ fontSize:14, fontWeight:800, color:"#1A1A1A" }}>{lane.name}</div>
                        <Chip status={lane.status} />
                        {(()=>{
                          // Show attendance trend: avg show-up across done sessions
                          const doneSessions = lane.sessions.filter(s=>s.status==="done"&&s.attendees>0);
                          if (doneSessions.length === 0) return null;
                          const avgAtt = Math.round(doneSessions.reduce((a,s)=>a+(s.attendees||0),0)/doneSessions.length);
                          const totalRsvpd = doneSessions.reduce((a,s)=>a+(s.rsvpCount||0),0);
                          const avgPct = totalRsvpd > 0 ? Math.round(doneSessions.reduce((a,s)=>a+(s.rsvpCount?((s.attendees||0)/s.rsvpCount)*100:0),0)/doneSessions.filter(s=>s.rsvpCount>0).length||0) : null;
                          return (
                            <span style={{ fontSize:10, background:"rgba(4,120,87,0.12)", color:C.teal, border:"1px solid rgba(52,211,153,0.25)", borderRadius:5, padding:"2px 8px", fontWeight:700 }}>
                              📊 avg {avgAtt}{avgPct?` · ${avgPct}% show-up`:""}
                            </span>
                          );
                        })()}
                        {canEdit && <>
                          <Btn v="ghost" sm onClick={e=>{e.stopPropagation();open("lane",{...lane},li);}}>✏️</Btn>
                          <Btn v="danger" sm onClick={e=>{e.stopPropagation();delLane(li);}}>🗑</Btn>
                        </>}
                      </div>
                      <div style={{ fontSize:11, color:"#6B7280", marginBottom:10 }}>{lane.mentor} · {lane.stream}</div>
                      <div style={{ display:"flex", alignItems:"center", gap:12 }}>
                        <Bar val={done} max={12} color="#047857" />
                        <span style={{ fontFamily:"monospace", fontSize:13, fontWeight:600, color:"#374151", flexShrink:0 }}>{done}/12 sessions</span>
                      </div>
                    </div>
                    <div style={{ marginLeft:16, fontSize:18, color:"#6B7280", flexShrink:0 }}>{isOpen?"▾":"▸"}</div>
                  </div>

                  {/* Session details */}
                  {isOpen && (
                    <div style={{ borderTop:"1px solid #E5E7EB", padding:"0 18px 18px" }}>
                      <div style={{ paddingTop:14, marginBottom:10, fontSize:11, color:"#6B7280", textTransform:"uppercase", letterSpacing:"0.06em", fontWeight:700 }}>
                        12 Sessions · {PERIODS.find(p=>p.key===period)?.label||"All Time"} view · {sessions.filter(s=>s.status==="done").length} done in this period
                      </div>
                      {(()=>{
                        // Attendance trend chart — per session RSVPs vs attended
                        const sessWithData = lane.sessions.filter(s=>s.status==="done"||s.rsvpCount>0||s.attendees>0);
                        if (sessWithData.length === 0) return null;
                        const maxVal = Math.max(...sessWithData.map(s=>Math.max(s.rsvpCount||0, s.attendees||0)), 1);
                        const doneSessions = lane.sessions.filter(s=>s.status==="done"&&s.attendees>0);
                        const avgPct = (()=>{
                          const withBoth = doneSessions.filter(s=>s.rsvpCount>0);
                          if (!withBoth.length) return null;
                          return Math.round(withBoth.reduce((a,s)=>a+((s.attendees||0)/s.rsvpCount)*100,0)/withBoth.length);
                        })();
                        return (
                          <div style={{ marginBottom:12, background:"rgba(4,120,87,0.05)", border:"1px solid rgba(52,211,153,0.15)", borderRadius:10, padding:"12px 14px" }}>
                            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:10 }}>
                              <span style={{ fontSize:10, fontWeight:700, color:C.teal, textTransform:"uppercase", letterSpacing:"0.07em" }}>📊 Attendance Trend</span>
                              {avgPct !== null && (
                                <span style={{ fontSize:10, background:"rgba(4,120,87,0.15)", color:C.teal, borderRadius:4, padding:"1px 8px", fontWeight:700, marginLeft:"auto" }}>
                                  avg show-up {avgPct}%
                                </span>
                              )}
                            </div>
                            {/* Bar chart */}
                            <div style={{ display:"flex", alignItems:"flex-end", gap:6, height:56 }}>
                              {lane.sessions.map((s,si)=>{
                                const rsvpH = s.rsvpCount ? Math.round((s.rsvpCount/maxVal)*48) : 0;
                                const attH  = s.attendees  ? Math.round((s.attendees/maxVal)*48)  : 0;
                                const isDone = s.status==="done";
                                return (
                                  <div key={s.id} style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:2, flex:1, position:"relative" }}
                                    title={`S${s.number}: ${s.rsvpCount||0} RSVPd · ${s.attendees||0} attended`}>
                                    <div style={{ display:"flex", alignItems:"flex-end", gap:1, height:48 }}>
                                      {rsvpH > 0 && <div style={{ width:6, height:rsvpH, background:"rgba(124,58,237,0.25)", borderRadius:"2px 2px 0 0" }} />}
                                      {attH  > 0 && <div style={{ width:6, height:attH,  background: isDone?"rgba(4,120,87,0.8)":"rgba(4,120,87,0.3)", borderRadius:"2px 2px 0 0" }} />}
                                      {!rsvpH && !attH && <div style={{ width:6, height:4, background:"rgba(0,0,0,0.04)", borderRadius:"2px 2px 0 0" }} />}
                                    </div>
                                    <div style={{ fontSize:8, color: isDone?C.teal:"#6B7280", fontWeight:isDone?700:400, fontFamily:"monospace" }}>S{s.number}</div>
                                  </div>
                                );
                              })}
                            </div>
                            <div style={{ display:"flex", gap:12, marginTop:6 }}>
                              <span style={{ fontSize:9, color:"rgba(180,83,9,0.7)" }}>■ RSVPd</span>
                              <span style={{ fontSize:9, color:"rgba(4,120,87,0.7)" }}>■ Attended</span>
                              <span style={{ fontSize:9, color:"#6B7280", marginLeft:"auto" }}>Hover bars for details</span>
                            </div>
                          </div>
                        );
                      })()}
                      <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                        {lane.sessions.map((sess,si)=>{
                          const inPeriod = sessionMatchesPeriod(sess, period);
                          return (
                            <div key={sess.id} style={{ display:"flex", alignItems:"flex-start", gap:12, padding:"10px 12px", background:sess.status==="done"?"rgba(4,120,87,0.06)":inPeriod&&period!=="all"?"rgba(4,120,87,0.05)":"#F9FAFB", border:`1px solid ${sess.status==="done"?"rgba(4,120,87,0.3)":inPeriod&&period!=="all"?"rgba(4,120,87,0.2)":"#E5E7EB"}`, borderRadius:8, opacity:period!=="all"&&!inPeriod?0.45:1 }}>
                              <div style={{ fontFamily:"monospace", fontSize:13, fontWeight:800, color:sess.status==="done"?C.green:"#6B7280", width:24, flexShrink:0, marginTop:1 }}>S{sess.number}</div>
                              <div style={{ flex:1 }}>
                                <div style={{ fontSize:13, fontWeight:600, color:"#1A1A1A" }}>{sess.title}</div>
                                <div style={{ fontSize:11, color:"#6B7280", marginTop:2 }}>
                                  {sess.date||"Date TBD"}{sess.attendees>0?` · ${sess.attendees} attendees`:""}
                                  {(()=>{
                                    // Per-session RSVP count (stored on sess.rsvpCount)
                                    if (!sess.rsvpCount) return null;
                                    const attended = sess.attendees || 0;
                                    const pct = attended > 0 ? Math.round((attended/sess.rsvpCount)*100) : null;
                                    return (
                                      <span style={{ marginLeft:6, fontSize:10, background:"rgba(4,120,87,0.15)", color:"#065F46", borderRadius:4, padding:"1px 6px", fontWeight:700 }}>
                                        📋 {sess.rsvpCount} RSVPs{attended>0?` · ${attended} attended${pct!==null?` (${pct}%)`:""}`:""}
                                      </span>
                                    );
                                  })()}

                                  {sess.recordingLink ? <> · <a href={sess.recordingLink} target="_blank" rel="noreferrer" style={{ color:C.teal }}>▶ Recording</a></> : ""}
                                  {sess.notes ? ` · ${sess.notes}` : ""}
                                </div>
                              </div>
                              <Chip status={sess.status==="done"?"done":sess.status==="planned"?"planned":"active"} label={sess.status==="done"?"Done":sess.status==="planned"?"Planned":"Ongoing"} />
                              {canEdit && (
                                <Btn v="ghost" sm onClick={()=>setSessionModal({laneIdx:li, idx:si, form:{...sess}})}>✏️</Btn>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </>
      )}

      {/* ── Expert Workshops ── */}
      {tab==="Contracts" && (
        <ContractsPanel
          contracts={data.contractSubmissions||data.atdp?.contractSubmissions||[]}
          students={students}
          onAddStudent={newStudent=>{
            const arr = [...students, newStudent];
            onUpdate({...data, students: arr});
          }}
          onDelete={idx=>{
            const updated = (data.contractSubmissions||data.atdp?.contractSubmissions||[]).filter((_,i)=>i!==idx);
            onUpdate({...data, contractSubmissions: updated});
          }}
        />
      )}

      {tab==="Expert Workshops" && (
        <>
          <div style={{ display:"flex", justifyContent:"flex-end", gap:8, marginBottom:14 }}>
            {canEdit && <Btn sm onClick={()=>open("ws",newWs())}>+ Add Workshop</Btn>}
            <Btn v="ghost" sm onClick={()=>exportCSV(ws,"workshops.csv")}>⬇ Export</Btn>
          </div>
          <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {ws.map((w,i)=>(
              <div key={w.id} style={{ background:"#F9FAFB", border:"1px solid #E5E7EB", borderRadius:10, padding:"13px 16px", display:"flex", alignItems:"flex-start", gap:14 }}>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:13, fontWeight:700, color:"#1A1A1A" }}>{w.name}</div>
                  <div style={{ fontSize:11, color:"#6B7280", marginTop:2 }}>
                    {w.mentor} · {w.date}{w.attendees?` · ${w.attendees} attendees`:""}
                  </div>
                  {w.recordingLink && <a href={w.recordingLink} target="_blank" rel="noreferrer" style={{ fontSize:11, color:C.teal, marginTop:4, display:"block" }}>▶ Recording</a>}
                  {w.notes && <div title={w.notes} style={{ fontSize:11, color:"#6B7280", marginTop:4, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", maxWidth:500, cursor:"help" }}>{w.notes}</div>}
                </div>
                <Chip status={w.status} />
                {canEdit && <><Btn v="ghost" sm onClick={()=>open("ws",{...w},i)}>✏️</Btn><Btn v="danger" sm onClick={()=>delWs(i)}>🗑</Btn></>}
              </div>
            ))}
          </div>
        </>
      )}

      {/* ── Column Manager Modal ── */}
      {showColMgr && (
        <Modal title="Manage Custom Columns" onClose={()=>setShowColMgr(false)}>
          <ColumnManager
            customFields={customFields}
            onAdd={addCustomField}
            onDelete={delCustomField}
            onRename={renameCustomField}
            onMove={moveCustomField}
            onClose={()=>setShowColMgr(false)}
          />
        </Modal>
      )}

      </>}
      {showImporter && <StudentImporter existingStudents={students} onImport={newOnes=>{ if(newOnes.length){ const arr=[...students,...newOnes]; onUpdate({...data,students:arr}); } setShowImporter(false); }} onClose={()=>setShowImporter(false)} />}
      {showRsvpImporter && <RSVPImporter onImport={sessions=>{ 
        // Merge into permanent RSVP history
        const existing = data.rsvpHistory || [];
        const merged = [...existing];
        sessions.forEach(ns => {
          const idx = merged.findIndex(e => e.name === ns.name && e.date === ns.date);
          if (idx >= 0) {
            const combined = [...(merged[idx].rsvps||[])];
            (ns.rsvps||[]).forEach(nr => {
              if (!combined.some(r => r.email === nr.email || (r.phone && r.phone === nr.phone))) combined.push(nr);
            });
            merged[idx] = { ...merged[idx], rsvps: combined, lastUpdated: new Date().toISOString() };
          } else {
            merged.push({ ...ns, lastUpdated: new Date().toISOString(), isNew: true });
          }
        });

        // Stitch RSVPs into Attendance Tracker for matching students
        let updatedStudents = [...(data.students||[])];
        sessions.forEach(rsvpSession => {
          // Find matching lane
          const ln = rsvpSession.name.toLowerCase().trim();
          const matchedLane = (data.groomingLanes||[]).find(l=>{ const ll=l.name.toLowerCase().trim(); return ll===ln||ln.includes(ll)||ll.includes(ln); });
          // Find next planned S in that lane
          const nextS = matchedLane ? (matchedLane.sessions||[]).filter(s=>s.status!=="done").sort((a,b)=>a.number-b.number)[0] : null;
          const sLabel = nextS ? `S${nextS.number}` : "";

          rsvpSession.rsvps.forEach(rsvp => {
            // Match student by name (first name match is enough)
            const rFirst = (rsvp.name||"").split(" ")[0].toLowerCase();
            const matchedStudent = updatedStudents.find(s => s.name.toLowerCase().split(" ")[0] === rFirst || s.name.toLowerCase().includes(rFirst));
            if (!matchedStudent) return;

            // Check if already logged for this lane + session
            const alreadyLogged = (matchedStudent.attendance||[]).some(a =>
              a.sessionType==="grooming" && a.sessionName===rsvpSession.name && a.sessionNumber===sLabel && a.presence==="rsvpd"
            );
            if (alreadyLogged) return;

            // Add RSVP attendance entry
            const newEntry = {
              id: `att_rsvp_${Date.now()}_${Math.random().toString(36).slice(2,6)}`,
              sessionType: "grooming",
              sessionName: rsvpSession.name,
              sessionNumber: sLabel,
              presence: "rsvpd",
              energy: "",
              notes: `RSVP'd via form · ${rsvpSession.date||""}`,
              date: new Date().toLocaleDateString("en-IN"),
            };
            updatedStudents = updatedStudents.map(s =>
              s.id === matchedStudent.id
                ? { ...s, attendance: [...(s.attendance||[]), newEntry] }
                : s
            );
          });
        });

        onUpdate({...data, rsvpSessions: sessions, rsvpHistory: merged, students: updatedStudents });
      }} onClose={()=>setShowRsvpImporter(false)} />}
      {profileStudent && <StudentProfileModal studentName={profileStudent} allData={fullData||{atdp:data}} anthropicKey={anthropicKey} onClose={()=>setProfileStudent(null)} />}
      <DeleteConfirmModal />
      {/* ── Modals ── */}
      {modal?.type==="student" && (
        <Modal title={modal.idx!==null?"Edit Student":"Add Student"} onClose={close} wide>
          <StudentForm initial={modal.form} customFields={customFields} onSave={saveStudent} onCancel={close} />
        </Modal>
      )}
      {modal?.type==="lane" && (
        <Modal title={modal.idx!==null?"Edit Lane":"Add Grooming Lane"} onClose={close}>
          <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12 }}>
              <Field label="Lane Name" value={modal.form.name} onChange={v=>setModal(p=>({...p,form:{...p.form,name:v}}))} />
              <Field label="Mentor" value={modal.form.mentor} onChange={v=>setModal(p=>({...p,form:{...p.form,mentor:v}}))} />
              <Field label="Stream" value={modal.form.stream} onChange={v=>setModal(p=>({...p,form:{...p.form,stream:v}}))} options={["All Streams",...STREAMS]} />
              <Field label="Status" value={modal.form.status} onChange={v=>setModal(p=>({...p,form:{...p.form,status:v}}))} options={["active","pending","on hold"]} />
            </div>
            <div style={{ display:"flex", gap:8, justifyContent:"flex-end", marginTop:8 }}>
              <Btn v="secondary" onClick={close}>Cancel</Btn>
              <Btn onClick={()=>saveLane(modal.form)}>Save</Btn>
            </div>
          </div>
        </Modal>
      )}
      {modal?.type==="ws" && (
        <Modal title={modal.idx!==null?"Edit Workshop":"Add Workshop"} onClose={close}>
          <WsForm initial={modal.form} onSave={saveWs} onCancel={close} />
        </Modal>
      )}
      {sessionModal && (
        <Modal title={`Edit Session ${sessionModal.form.number} — ${lanes[sessionModal.laneIdx]?.name}`} onClose={()=>setSessionModal(null)}>
          <SessionForm initial={sessionModal.form} onSave={f=>saveSession(sessionModal.laneIdx,f)} onCancel={()=>setSessionModal(null)} />
        </Modal>
      )}
      {markAttSession && (
        <MarkAttendanceModal
          session={markAttSession}
          students={students}
          data={data}
          onUpdate={onUpdate}
          onClose={()=>setMarkAttSession(null)}
        />
      )}
    </div>
  );
}

function StudentForm({ initial, customFields, onSave, onCancel }) {
  const [f, setF] = useState({...initial, custom:{...initial.custom}});
  const u = (k,v) => setF(p=>({...p,[k]:v}));
  const uc = (k,v) => setF(p=>({...p,custom:{...p.custom,[k]:v}}));
  return (
    <div>
      <Divider label="Personal Info" />
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12 }}>
        <Field label="Full Name" value={f.name} onChange={v=>u("name",v)} />
        <Field label="Age" type="number" value={f.age} onChange={v=>u("age",v)} />
        <Field label="Gender" value={f.gender||""} onChange={v=>u("gender",v)} options={["","Male","Female","Non-binary","Prefer not to say"]} />
        <Field label="City" value={f.city} onChange={v=>u("city",v)} />
        <Field label="Phone" value={f.phone} onChange={v=>u("phone",v)} />
        <Field label="Email" value={f.email} onChange={v=>u("email",v)} />
        <Field label="Parent / Guardian Name" value={f.parentName} onChange={v=>u("parentName",v)} />
        <Field label="Parent Phone" value={f.parentPhone} onChange={v=>u("parentPhone",v)} />
      </div>
      <Divider label="Programme Details" />
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12 }}>
        <div>
          <div style={{ fontSize:11, fontWeight:600, color:"#374151", marginBottom:6 }}>Stream(s)</div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
            {STREAMS.map(s=>{
              const streams = f.streams || (f.stream ? [f.stream] : []);
              const active = streams.includes(s);
              return (
                <button key={s} type="button"
                  onClick={()=>{
                    const cur = f.streams || (f.stream ? [f.stream] : []);
                    const next = cur.includes(s) ? cur.filter(x=>x!==s) : [...cur, s];
                    u("streams", next);
                    u("stream", next[0]||"");
                    // Auto-populate teachers{} when first adding multi-stream
                    if (next.length > 1 && f.teacher && !f.teachers?.[next[0]]) {
                      u("teachers", { ...(f.teachers||{}), [next[0]]: f.teacher });
                    }
                  }}
                  style={{ padding:"4px 10px", borderRadius:6, border:`1px solid ${active?"#1E40AF":"#E5E7EB"}`,
                    background:active?"rgba(30,64,175,0.08)":"#F9FAFB", color:active?"#1E40AF":"#6B7280",
                    fontSize:11, fontWeight:active?700:500, cursor:"pointer", fontFamily:"inherit", transition:"all 0.15s" }}>
                  {s}
                </button>
              );
            })}
          </div>
          {(f.streams||[]).length > 0 && (
            <div style={{ fontSize:10, color:"#9CA3AF", marginTop:4 }}>
              Selected: {(f.streams||[f.stream]).filter(Boolean).join(", ")}
            </div>
          )}
        </div>
        <Field label="Joined (e.g. Jan 2026)" value={f.joined} onChange={v=>u("joined",v)} />
        {/* ── Per-stream teacher assignment ── */}
        {f.streams && f.streams.length > 1
          ? <div style={{ gridColumn:"1/-1" }}>
              <div style={{ fontSize:11, fontWeight:600, color:"#374151", marginBottom:8, textTransform:"uppercase", letterSpacing:"0.08em" }}>Teachers / Mentors</div>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                {f.streams.map(stream => (
                  <div key={stream} style={{ display:"flex", flexDirection:"column", gap:5 }}>
                    <div style={{ fontSize:10, fontWeight:700, color:"#6B7280", textTransform:"uppercase", letterSpacing:"0.08em" }}>{stream}</div>
                    <input
                      value={(f.teachers||{})[stream] || ""}
                      onChange={e => {
                        const updated = { ...(f.teachers||{}), [stream]: e.target.value };
                        u("teachers", updated);
                        u("teacher", updated[f.streams[0]] || "");
                      }}
                      placeholder={"Teacher for " + stream}
                      style={{ background:"#F9FAFB", border:"1px solid #E5E7EB", borderRadius:8, padding:"8px 12px",
                        color:"#1A1A1A", fontFamily:"inherit", fontSize:13, outline:"none",
                        transition:"border-color 0.15s" }}
                      onFocus={e=>{ e.target.style.borderColor="#1E40AF"; }}
                      onBlur={e=>{ e.target.style.borderColor="#E5E7EB"; }}
                    />
                  </div>
                ))}
              </div>
              <div style={{ fontSize:10, color:"#9CA3AF", marginTop:6 }}>
                Each stream can have a different teacher. The first stream's teacher is shown as primary.
              </div>
            </div>
          : <Field label="Teacher / Mentor" value={f.teacher} onChange={v=>u("teacher",v)} />
        }
        <Field label="Status" value={f.status} onChange={v=>u("status",v)} options={["active","inactive","on hold"]} />
        <Field label="Contract Signed?" value={f.contract?"Yes":"No"} onChange={v=>u("contract",v==="Yes")} options={["Yes","No"]} />
      </div>
      {customFields?.length > 0 && <>
        <Divider label="Custom Fields" />
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12 }}>
          {customFields.map(cf=><Field key={cf} label={cf} value={f.custom?.[cf]||""} onChange={v=>uc(cf,v)} />)}
        </div>
      </>}
      <Divider label="Notes" />
      <Field value={f.notes} onChange={v=>u("notes",v)} textarea />
      <div style={{ display:"flex", gap:8, justifyContent:"flex-end", marginTop:18 }}>
        <Btn v="secondary" onClick={onCancel}>Cancel</Btn>
        <Btn onClick={()=>onSave(f)}>Save Student</Btn>
      </div>
    </div>
  );
}

