// ═══════════════════════════════════════════════════════════════════════════
// INTELLIGENT DEADLINE SYSTEM v4
// ─ parseDeadlineDate, formatDeadline
// ─ DEPENDENCY_RULES  (known task chains)
// ─ computeSuggestedDeadline
// ─ computeBufferHealth
// ─ EditableCell
// ─ DeadlineDatePicker  (mini calendar with task dots + suggested date chip)
// ─ DeadlineRow  (all fields editable; shows suggested date + buffer health)
// ─ TodayDigest  (pinned card: today/overdue/stalled/tomorrow preview)
// ─ WorkloadHeatmap  (14-day strip, task count per day)
// ─ DLColumnHeaders, DLGroup, AddTaskModal
// ─ DeadlinesSection  (main orchestrator)
// ═══════════════════════════════════════════════════════════════════════════

// ─── DEADLINES SECTION (simple) ───────────────────────────────────────────────

function parseDeadlineDate(str) {
  if (!str || str === "" || str === "NAN") return null;
  const s = str.trim();
  if (s === "Day +1" || s === "Release Day") return null;
  const cleaned = s.replace(/[–—\-].*/g, "").trim();
  const mo = cleaned.match(/^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d+)(?:\s+(\d{4}))?$/i);
  if (mo) { const y = mo[3] ? parseInt(mo[3]) : 2026; return new Date(`${mo[1]} ${mo[2]}, ${y}`); }
  return null;
}
function formatDeadline(d) {
  if (!d) return "";
  const M = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  return `${M[d.getMonth()]} ${d.getDate()}`;
}
function addDays(d, n) { const r = new Date(d); r.setDate(r.getDate() + n); return r; }

// ── Mini calendar popup ────────────────────────────────────────────────────────
function DatePickerPopup({ value, onChange, allTasks, taskId, onClose }) {
  const MONTHS   = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const DOW      = ["Su","Mo","Tu","We","Th","Fr","Sa"];
  const STATUS_COLOR = { "URGENT":"#DC2626","Pending":"#F59E0B","In Progress":"#3B82F6","Done":"#10B981" };

  const sel = parseDeadlineDate(value);
  const [vy, setVY] = React.useState(sel ? sel.getFullYear() : 2026);
  const [vm, setVM] = React.useState(sel ? sel.getMonth() : 3);

  const today = new Date(); today.setHours(0,0,0,0);
  const dim   = new Date(vy, vm+1, 0).getDate();
  const start = new Date(vy, vm, 1).getDay();

  // tasks per day for dot indicators
  const dotMap = React.useMemo(() => {
    const m = {};
    allTasks.forEach(t => {
      const d = parseDeadlineDate(t.deadline);
      if (!d) return;
      const k = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
      if (!m[k]) m[k] = [];
      m[k].push(t);
    });
    return m;
  }, [allTasks]);

  const prevM = () => { let m=vm-1,y=vy; if(m<0){m=11;y--;} setVM(m); setVY(y); };
  const nextM = () => { let m=vm+1,y=vy; if(m>11){m=0;y++;} setVM(m); setVY(y); };

  const pick = (day) => {
    onChange(formatDeadline(new Date(vy, vm, day)));
    onClose();
  };

  return (
    <div style={{ position:"absolute", top:"calc(100% + 4px)", left:0, zIndex:9999,
      background:"#FFF", borderRadius:12, boxShadow:"0 8px 32px rgba(0,0,0,0.18)",
      border:"1px solid #E5E7EB", width:260, overflow:"hidden" }}
      onMouseDown={e => e.stopPropagation()}>

      {/* Month nav */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
        padding:"10px 14px", borderBottom:"1px solid #F3F4F6" }}>
        <button onClick={prevM} style={{ background:"none", border:"none", cursor:"pointer",
          fontSize:18, color:"#6B7280", lineHeight:1, padding:"0 4px" }}>‹</button>
        <span style={{ fontSize:13, fontWeight:800, color:"#1A1A1A" }}>{MONTHS[vm]} {vy}</span>
        <button onClick={nextM} style={{ background:"none", border:"none", cursor:"pointer",
          fontSize:18, color:"#6B7280", lineHeight:1, padding:"0 4px" }}>›</button>
      </div>

      {/* DOW row */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(7,1fr)", padding:"6px 8px 0" }}>
        {DOW.map(d => <div key={d} style={{ textAlign:"center", fontSize:9,
          fontWeight:700, color:"#9CA3AF", padding:"2px 0" }}>{d}</div>)}
      </div>

      {/* Days grid */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(7,1fr)",
        padding:"4px 8px 10px", gap:2 }}>
        {Array.from({length:start}).map((_,i) => <div key={`e${i}`}/>)}
        {Array.from({length:dim}).map((_,i) => {
          const day    = i+1;
          const dayKey = `${vy}-${vm}-${day}`;
          const dots   = dotMap[dayKey] || [];
          const thisD  = new Date(vy, vm, day);
          const isSel  = sel && sel.getFullYear()===vy && sel.getMonth()===vm && sel.getDate()===day;
          const isTod  = today.getFullYear()===vy && today.getMonth()===vm && today.getDate()===day;
          const isPast = thisD < today;
          return (
            <div key={day} onClick={() => pick(day)}
              style={{ position:"relative", textAlign:"center", padding:"4px 2px 6px",
                borderRadius:7, cursor:"pointer", minHeight:34,
                background: isSel ? "#1A1A1A" : isTod ? "#F3F4F6" : "transparent",
                border: isSel ? "none" : isTod ? "1px solid #E5E7EB" : "1px solid transparent" }}
              onMouseEnter={e=>{ if(!isSel) e.currentTarget.style.background="#F3F4F6"; }}
              onMouseLeave={e=>{ if(!isSel) e.currentTarget.style.background=isTod?"#F3F4F6":"transparent"; }}>
              <div style={{ fontSize:11, fontWeight:isSel||isTod?700:400,
                color: isSel?"#FFF" : isPast?"#D1D5DB" : "#1A1A1A" }}>
                {day}
              </div>
              {dots.length > 0 && (
                <div style={{ display:"flex", justifyContent:"center", gap:1,
                  position:"absolute", bottom:2, left:0, right:0 }}>
                  {dots.slice(0,3).map((t,di) => (
                    <div key={di} style={{ width:4, height:4, borderRadius:"50%",
                      background: isSel ? "rgba(255,255,255,0.7)" : (STATUS_COLOR[t.status]||"#9CA3AF"),
                      border: t.id===taskId&&!isSel ? "1px solid #1A1A1A" : "none" }}/>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Other tasks on selected date */}
      {sel && (() => {
        const k = `${sel.getFullYear()}-${sel.getMonth()}-${sel.getDate()}`;
        const on = dotMap[k] || [];
        if (!on.length) return null;
        return (
          <div style={{ borderTop:"1px solid #F3F4F6", padding:"8px 14px", maxHeight:100, overflowY:"auto" }}>
            <div style={{ fontSize:9, fontWeight:700, color:"#9CA3AF", textTransform:"uppercase",
              letterSpacing:"0.08em", marginBottom:4 }}>Also on {value}:</div>
            {on.map(t => (
              <div key={t.id} style={{ display:"flex", alignItems:"center", gap:5,
                padding:"2px 0", fontSize:10,
                color: t.id===taskId ? "#2563EB" : "#6B7280",
                fontWeight: t.id===taskId ? 700 : 400 }}>
                <div style={{ width:5, height:5, borderRadius:"50%", flexShrink:0,
                  background: STATUS_COLOR[t.status]||"#9CA3AF" }}/>
                {t.task}
              </div>
            ))}
          </div>
        );
      })()}

      {/* Clear */}
      {value && (
        <div style={{ borderTop:"1px solid #F3F4F6", padding:"6px 14px" }}>
          <button onClick={() => { onChange(""); onClose(); }}
            style={{ fontSize:10, color:"#9CA3AF", background:"none", border:"none",
              cursor:"pointer", fontFamily:"inherit" }}>
            ✕ Clear date
          </button>
        </div>
      )}
    </div>
  );
}

// ── Single task row ────────────────────────────────────────────────────────────
function DLTaskRow({ task, today, updateTask, deleteTask, allTasks }) {
  const [showCal, setShowCal] = React.useState(false);
  const rowRef = React.useRef(null);

  const d        = parseDeadlineDate(task.deadline);
  const daysLeft = d ? Math.round((d - today) / 86400000) : null;
  const overdue  = daysLeft !== null && daysLeft < 0 && task.status !== "Done";
  const soon     = daysLeft !== null && daysLeft <= 2 && daysLeft >= 0 && task.status !== "Done";
  const isDone   = task.status === "Done";

  // Close calendar on outside click
  React.useEffect(() => {
    if (!showCal) return;
    const h = (e) => { if (rowRef.current && !rowRef.current.contains(e.target)) setShowCal(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, [showCal]);

  const STATUS_OPTS = ["Pending","In Progress","Done","URGENT"];
  const STATUS_STYLE = {
    "Pending":     { bg:"#FFFBEB", color:"#92400E" },
    "In Progress": { bg:"#EFF6FF", color:"#1E40AF" },
    "Done":        { bg:"#F0FDF4", color:"#065F46" },
    "URGENT":      { bg:"#FEF2F2", color:"#991B1B" },
  };
  const ss = STATUS_STYLE[task.status] || STATUS_STYLE["Pending"];

  const set = (field) => (e) =>
    updateTask(task.id, { ...task, [field]: typeof e === "string" ? e : e.target.value });

  return (
    <div ref={rowRef} style={{ display:"flex", alignItems:"flex-start", gap:10,
      padding:"10px 14px", borderBottom:"1px solid #F8F8F8",
      background: isDone ? "#FAFAFA" : overdue ? "#FFF5F5" : "#FFF",
      opacity: isDone ? 0.65 : 1, position:"relative" }}>

      {/* Left accent bar */}
      <div style={{ width:3, alignSelf:"stretch", borderRadius:2, flexShrink:0, marginTop:2,
        background: isDone ? "#D1FAE5" : overdue ? "#FCA5A5" : soon ? "#FCD34D" : "#E5E7EB" }}/>

      {/* Main content */}
      <div style={{ flex:1, minWidth:0 }}>
        {/* Task title — inline editable */}
        <input value={task.task} onChange={set("task")}
          style={{ width:"100%", border:"none", outline:"none", background:"transparent",
            fontSize:13, fontWeight:600, color: isDone?"#9CA3AF":"#1A1A1A",
            textDecoration: isDone?"line-through":"none",
            fontFamily:"inherit", padding:0, marginBottom:2 }}/>
        {/* Notes */}
        {(task.notes && task.notes !== "nan") && (
          <div style={{ fontSize:11, color:"#9CA3AF" }}>{task.notes}</div>
        )}
        {/* Meta row: owner · deadline */}
        <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:4, flexWrap:"wrap" }}>
          {/* Owner */}
          <input value={task.owner||""} onChange={set("owner")} placeholder="Owner"
            style={{ border:"none", outline:"none", background:"transparent",
              fontSize:11, color:"#6B7280", fontFamily:"inherit", padding:0,
              minWidth:60, maxWidth:160 }}/>

          {/* Deadline */}
          <div style={{ position:"relative" }}>
            <button onClick={() => setShowCal(c=>!c)}
              style={{ display:"flex", alignItems:"center", gap:4, background:"none",
                border:"none", cursor:"pointer", padding:0, fontFamily:"inherit" }}>
              <span style={{ fontSize:11, fontWeight:600,
                color: !task.deadline?"#D1D5DB": overdue?"#DC2626": soon?"#D97706":"#374151" }}>
                📅 {task.deadline || "Set date"}
              </span>
              {daysLeft !== null && !isDone && (
                <span style={{ fontSize:10, fontWeight:700, padding:"1px 5px", borderRadius:4,
                  background: overdue?"#FEE2E2":soon?"#FEF3C7":"#F3F4F6",
                  color: overdue?"#DC2626":soon?"#92400E":"#9CA3AF" }}>
                  {overdue ? `${Math.abs(daysLeft)}d late` : daysLeft===0 ? "Today" : `${daysLeft}d`}
                </span>
              )}
            </button>
            {showCal && (
              <DatePickerPopup value={task.deadline||""} onChange={set("deadline")}
                allTasks={allTasks} taskId={task.id} onClose={()=>setShowCal(false)}/>
            )}
          </div>
        </div>
      </div>

      {/* Status selector */}
      <div style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:6, flexShrink:0 }}>
        <select value={task.status} onChange={e=>updateTask(task.id,{...task,status:e.target.value})}
          style={{ padding:"3px 8px", borderRadius:6, border:`1px solid ${ss.bg}`,
            background:ss.bg, color:ss.color, fontSize:10, fontWeight:700,
            cursor:"pointer", outline:"none", fontFamily:"inherit" }}>
          {STATUS_OPTS.map(v=><option key={v}>{v}</option>)}
        </select>
        {task.custom && (
          <button onClick={()=>deleteTask(task.id)}
            style={{ fontSize:9, color:"#D1D5DB", background:"none", border:"none",
              cursor:"pointer", fontFamily:"inherit", padding:0 }}>
            remove
          </button>
        )}
      </div>
    </div>
  );
}

// ── Add Task form (inline, no modal) ──────────────────────────────────────────
function DLAddRow({ defaultSheet, onAdd, onCancel }) {
  const SHEETS = ["🎵 Devotional","🎤 unMute","🎼 Originals","📚 Grooming & Workshop","🏠 This Week"];
  const [form, setForm] = React.useState({ task:"", owner:"Abhijeet", deadline:"", sheet:defaultSheet||SHEETS[0] });
  const s = (k) => (e) => setForm(p=>({...p,[k]:e.target.value}));
  const inp = (k, ph, w) => (
    <input value={form[k]} onChange={s(k)} placeholder={ph}
      style={{ flex:w||1, padding:"6px 10px", borderRadius:7, border:"1px solid #E5E7EB",
        fontSize:12, outline:"none", fontFamily:"inherit", minWidth:0 }}/>
  );
  return (
    <div style={{ padding:"10px 14px", background:"#F8FAFF", borderBottom:"1px solid #E5E7EB",
      display:"flex", flexDirection:"column", gap:8 }}>
      <div style={{ display:"flex", gap:6 }}>
        {inp("task","Task description…")}
        {inp("owner","Owner",0)}
        {inp("deadline","Apr 20",0)}
      </div>
      <div style={{ display:"flex", gap:6, alignItems:"center" }}>
        <select value={form.sheet} onChange={s("sheet")}
          style={{ flex:1, padding:"6px 10px", borderRadius:7, border:"1px solid #E5E7EB",
            fontSize:12, fontFamily:"inherit", outline:"none" }}>
          {SHEETS.map(sh=><option key={sh}>{sh}</option>)}
        </select>
        <button onClick={()=>{ if(!form.task.trim()) return;
            onAdd({...form,id:`custom_${Date.now()}`,section:"",custom:true,status:"Pending",notes:""});
          }}
          style={{ padding:"6px 16px", background:"#1A1A1A", color:"#FFF", border:"none",
            borderRadius:7, cursor:"pointer", fontSize:12, fontWeight:700, fontFamily:"inherit" }}>
          Add
        </button>
        <button onClick={onCancel}
          style={{ padding:"6px 12px", background:"none", color:"#9CA3AF", border:"none",
            cursor:"pointer", fontSize:12, fontFamily:"inherit" }}>
          Cancel
        </button>
      </div>
    </div>
  );
}

// ── Main DeadlinesSection ──────────────────────────────────────────────────────
function DeadlinesSection({ canEdit=true, anthropicKey }) {
  const SK = "artium-dl-v5";
  const CK = "artium-dl-col-v5";

  const [store,   setStore]   = React.useState(()=>{ try{return JSON.parse(localStorage.getItem(SK)||"{}");}catch{return{};} });
  const [customs, setCustoms] = React.useState(()=>{ try{const s=JSON.parse(localStorage.getItem(SK)||"{}"); return Object.values(s).filter(t=>t.custom&&t.task);}catch{return[];} });
  const [collapsed,setCol]    = React.useState(()=>{ try{return JSON.parse(localStorage.getItem(CK)||"{}");}catch{return{};} });
  const [tab,     setTab]     = React.useState("today");
  const [project, setProject] = React.useState("🎵 Devotional");
  const [filter,  setFilter]  = React.useState("all");
  const [showAdd, setShowAdd] = React.useState(false);
  const [aiText,  setAiText]  = React.useState("");
  const [aiLoad,  setAiLoad]  = React.useState(false);

  const today = React.useMemo(()=>{ const d=new Date();d.setHours(0,0,0,0);return d; },[]);

  const persist = React.useCallback((s, c) => {
    const m = {...s}; c.forEach(t=>{m[t.id]=t;});
    try{localStorage.setItem(SK,JSON.stringify(m));}catch{}
  },[]);

  const tasks = React.useMemo(()=>[
    ...DEADLINES_TASKS_RAW.map(t=>({...t,...(store[t.id]||{})})),
    ...customs
  ],[store,customs]);

  const enriched = React.useMemo(()=>tasks.map(t=>{
    const d = parseDeadlineDate(t.deadline);
    const dl = d ? Math.round((d-today)/86400000) : null;
    return {...t, daysLeft:dl, month: d?d.getMonth():null};
  }),[tasks,today]);

  const updateTask = React.useCallback((id,upd)=>{
    if(upd.custom){
      setCustoms(prev=>{ const n=prev.map(t=>t.id===id?upd:t); setStore(s=>{persist(s,n);return s;}); return n; });
    } else {
      setStore(prev=>{ const n={...prev,[id]:{...(prev[id]||{}),...upd}}; persist(n,customs); return n; });
    }
  },[customs,persist]);

  const deleteTask = React.useCallback((id)=>{
    setCustoms(prev=>{ const n=prev.filter(t=>t.id!==id); setStore(s=>{const ns={...s};delete ns[id];persist(ns,n);return ns;}); return n; });
  },[persist]);

  const addTask = React.useCallback((t)=>{
    setCustoms(prev=>{ const n=[...prev,t]; setStore(s=>{persist(s,n);return s;}); return n; });
  },[persist]);

  const toggleSection = (k) => setCol(prev=>{
    const n={...prev,[k]:!prev[k]};
    try{localStorage.setItem(CK,JSON.stringify(n));}catch{} return n;
  });

  // Stats
  const total   = enriched.filter(t=>t.status!=="TARGET").length;
  const done    = enriched.filter(t=>t.status==="Done").length;
  const urgent  = enriched.filter(t=>t.status==="URGENT").length;
  const overdue = enriched.filter(t=>t.daysLeft!=null&&t.daysLeft<0&&t.status!=="Done"&&t.status!=="TARGET").length;

  // Today tasks: overdue + due today + due in 3 days
  const todayTasks = enriched
    .filter(t=>t.status!=="Done"&&t.status!=="TARGET"&&(
      (t.daysLeft!=null&&t.daysLeft<=3)
    ))
    .sort((a,b)=>(a.daysLeft??99)-(b.daysLeft??99));

  // This week
  const weekTasks = enriched
    .filter(t=>t.status!=="Done"&&t.status!=="TARGET"&&(
      t.status==="URGENT"||(t.daysLeft!=null&&t.daysLeft<=7)
    ))
    .sort((a,b)=>(a.daysLeft??99)-(b.daysLeft??99));

  const PROJECTS = [
    {key:"🎵 Devotional",         label:"🎵 Devotional"},
    {key:"🎤 unMute",             label:"🎤 unMute"},
    {key:"🎼 Originals",          label:"🎼 Originals"},
    {key:"📚 Grooming & Workshop",label:"📚 Grooming"},
  ];

  const applyFilter = l => {
    if(filter==="pending")    return l.filter(t=>t.status==="Pending");
    if(filter==="inprogress") return l.filter(t=>t.status==="In Progress");
    if(filter==="urgent")     return l.filter(t=>t.status==="URGENT");
    if(filter==="done")       return l.filter(t=>t.status==="Done");
    return l;
  };

  const exportCSV = () => {
    const rows=[["Sheet","Task","Owner","Deadline","Status","Notes"]];
    tasks.forEach(t=>rows.push([t.sheet,t.task,t.owner||"",t.deadline||"",t.status,t.notes||""]));
    const csv=rows.map(r=>r.map(v=>`"${(v||"").replace(/"/g,'""')}`).join(",")).join("\n");
    const a=document.createElement("a"); a.href="data:text/csv;charset=utf-8,"+encodeURIComponent(csv);
    a.download="ATDP-Deadlines.csv"; a.click();
  };

  const getAI = async () => {
    const key = anthropicKey || (typeof localStorage!=="undefined"&&localStorage.getItem("artium-anthropic-key"))||"";
    if(!key){setAiText("No API key found in Settings.");return;}
    setAiLoad(true); setAiText("");
    const urgent_tasks = enriched.filter(t=>t.status==="URGENT"||(t.daysLeft!=null&&t.daysLeft<=3&&t.status!=="Done"));
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages",{method:"POST",
        headers:{"Content-Type":"application/json","x-api-key":key,"anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},
        body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:200,
          messages:[{role:"user",content:`You're a concise project assistant. Artium Talent Dept tasks due soon:\n${urgent_tasks.map(t=>`- ${t.task} | ${t.deadline||"no date"} | ${t.status}`).join("\n")}\nGive 2-3 sentences: biggest risk + one action for Abhijeet. Be direct.`}]})});
      const data = await res.json();
      setAiText(data.content?.find(b=>b.type==="text")?.text||"No response.");
    } catch { setAiText("Error. Check API key."); }
    setAiLoad(false);
  };

  // ── Render helpers ──────────────────────────────────────────────────────────
  const rowProps = { today, updateTask, deleteTask, allTasks:enriched };

  const SectionBlock = ({ title, tasks: ts, accent="#2563EB" }) => {
    const key = `sec_${title}`;
    const isCol = collapsed[key];
    const doneC = ts.filter(t=>t.status==="Done").length;
    return (
      <div style={{ marginBottom:8, borderRadius:10, border:"1px solid #F0F0ED", overflow:"hidden" }}>
        <div onClick={()=>toggleSection(key)}
          style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
            padding:"9px 14px", cursor:"pointer", background:"#FAFAFA", userSelect:"none" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <span style={{ fontSize:11, transform:isCol?"rotate(-90deg)":"rotate(0deg)",
              transition:"transform 0.15s", display:"inline-block", color:"#9CA3AF" }}>▾</span>
            <span style={{ fontSize:12, fontWeight:700, color:"#1A1A1A" }}>{title}</span>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ width:48, height:3, background:"#F3F4F6", borderRadius:999 }}>
              <div style={{ width:`${ts.length>0?doneC/ts.length*100:0}%`,
                height:3, background:accent, borderRadius:999 }}/>
            </div>
            <span style={{ fontSize:10, color:"#9CA3AF" }}>{doneC}/{ts.length}</span>
          </div>
        </div>
        {!isCol && applyFilter(ts).map(t=>(
          <DLTaskRow key={t.id} task={t} {...rowProps}/>
        ))}
      </div>
    );
  };

  const TAB = (k,l) => (
    <button onClick={()=>setTab(k)} style={{ padding:"6px 14px", borderRadius:8,
      border:`1px solid ${tab===k?"#1A1A1A":"#E5E7EB"}`,
      background:tab===k?"#1A1A1A":"transparent",
      color:tab===k?"#FFF":"#6B7280",
      cursor:"pointer", fontSize:11, fontWeight:700,
      fontFamily:"inherit", whiteSpace:"nowrap" }}>
      {l}
    </button>
  );

  const FILTER = (k,l) => (
    <button onClick={()=>setFilter(f=>f===k?"all":k)} style={{ padding:"3px 10px",
      borderRadius:6, border:"none",
      background:filter===k?"#374151":"#F3F4F6",
      color:filter===k?"#FFF":"#6B7280",
      cursor:"pointer", fontSize:10, fontWeight:600, fontFamily:"inherit" }}>
      {l}
    </button>
  );

  return (
    <div>
      {/* ── Header ── */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:14 }}>
        <div>
          <h2 style={{ fontSize:18, fontWeight:800, color:"#1A1A1A", margin:0 }}>📋 Deadlines</h2>
          <div style={{ fontSize:11, color:"#9CA3AF", marginTop:2 }}>ATDP Apr–May 2026</div>
        </div>
        <div style={{ display:"flex", gap:6 }}>
          <button onClick={getAI} disabled={aiLoad}
            style={{ padding:"6px 12px", background:"#F5F3FF", color:"#6D28D9",
              border:"1px solid #DDD6FE", borderRadius:8, cursor:"pointer",
              fontSize:11, fontWeight:700, fontFamily:"inherit", opacity:aiLoad?0.6:1 }}>
            {aiLoad?"…":"✦ Briefing"}
          </button>
          <button onClick={()=>setShowAdd(s=>!s)}
            style={{ padding:"6px 12px", background:"#1A1A1A", color:"#FFF",
              border:"none", borderRadius:8, cursor:"pointer",
              fontSize:11, fontWeight:700, fontFamily:"inherit" }}>
            + Add
          </button>
          <button onClick={exportCSV}
            style={{ padding:"6px 12px", background:"transparent", color:"#6B7280",
              border:"1px solid #E5E7EB", borderRadius:8, cursor:"pointer",
              fontSize:11, fontFamily:"inherit" }}>
            Export
          </button>
        </div>
      </div>

      {/* ── AI briefing ── */}
      {aiText && (
        <div style={{ background:"#F5F3FF", border:"1px solid #DDD6FE", borderRadius:10,
          padding:"12px 16px", marginBottom:12, fontSize:12, color:"#374151",
          lineHeight:1.6, position:"relative" }}>
          <button onClick={()=>setAiText("")} style={{ position:"absolute", top:8, right:10,
            background:"none", border:"none", cursor:"pointer", color:"#9CA3AF", fontSize:14 }}>✕</button>
          <strong style={{color:"#6D28D9"}}>✦ Briefing: </strong>{aiText}
        </div>
      )}

      {/* ── Stats strip ── */}
      <div style={{ display:"flex", gap:8, marginBottom:14 }}>
        {[
          {l:"Done",    v:`${done}/${total}`, c:"#047857"},
          {l:"Urgent",  v:urgent,             c:urgent>0?"#DC2626":"#9CA3AF"},
          {l:"Overdue", v:overdue,            c:overdue>0?"#DC2626":"#9CA3AF"},
        ].map(s=>(
          <div key={s.l} style={{ flex:1, background:"#FFF", borderRadius:8, padding:"8px 12px",
            border:"1px solid #F0F0ED", textAlign:"center" }}>
            <div style={{ fontSize:17, fontWeight:800, color:s.c }}>{s.v}</div>
            <div style={{ fontSize:9, color:"#9CA3AF", fontWeight:700,
              textTransform:"uppercase", letterSpacing:"0.06em" }}>{s.l}</div>
          </div>
        ))}
        {/* Progress bar fills remaining space */}
        <div style={{ flex:3, display:"flex", flexDirection:"column", justifyContent:"center",
          background:"#FFF", borderRadius:8, padding:"8px 14px", border:"1px solid #F0F0ED" }}>
          <div style={{ display:"flex", justifyContent:"space-between", marginBottom:5 }}>
            <span style={{ fontSize:10, color:"#6B7280", fontWeight:600 }}>Overall progress</span>
            <span style={{ fontSize:10, color:"#047857", fontWeight:700 }}>{Math.round(done/Math.max(total,1)*100)}%</span>
          </div>
          <div style={{ background:"#F3F4F6", borderRadius:999, height:6 }}>
            <div style={{ background:"#047857", height:6, borderRadius:999,
              width:`${done/Math.max(total,1)*100}%`, transition:"width 0.4s" }}/>
          </div>
        </div>
      </div>

      {/* ── Tabs ── */}
      <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:10 }}>
        {TAB("today","🔥 Today")}
        {TAB("week","📅 This Week")}
        {TAB("project","📂 By Project")}
        {TAB("all","All")}
      </div>

      {/* ── Filter chips (not on today tab) ── */}
      {tab!=="today" && (
        <div style={{ display:"flex", gap:4, marginBottom:10, flexWrap:"wrap" }}>
          {FILTER("urgent","🔴 Urgent")}
          {FILTER("pending","⏳ Pending")}
          {FILTER("inprogress","🔵 In Progress")}
          {FILTER("done","✅ Done")}
        </div>
      )}

      {/* ── Add task inline ── */}
      {showAdd && <DLAddRow defaultSheet={project} onAdd={t=>{addTask(t);setShowAdd(false);}} onCancel={()=>setShowAdd(false)}/>}

      {/* ── TODAY ── */}
      {tab==="today" && (
        <div style={{ background:"#FFF", borderRadius:10, border:"1px solid #F0F0ED", overflow:"hidden" }}>
          {todayTasks.length===0 ? (
            <div style={{ padding:40, textAlign:"center", color:"#9CA3AF", fontSize:13 }}>
              🎉 Nothing due in the next 3 days. You're ahead.
            </div>
          ) : todayTasks.map(t=><DLTaskRow key={t.id} task={t} {...rowProps}/>)}
        </div>
      )}

      {/* ── THIS WEEK ── */}
      {tab==="week" && (
        <div style={{ background:"#FFF", borderRadius:10, border:"1px solid #F0F0ED", overflow:"hidden" }}>
          {weekTasks.length===0 ? (
            <div style={{ padding:40, textAlign:"center", color:"#9CA3AF", fontSize:13 }}>
              🎉 Nothing due this week.
            </div>
          ) : applyFilter(weekTasks).map(t=><DLTaskRow key={t.id} task={t} {...rowProps}/>)}
        </div>
      )}

      {/* ── BY PROJECT ── */}
      {tab==="project" && (
        <div>
          {/* Project selector */}
          <div style={{ display:"flex", gap:4, flexWrap:"wrap", marginBottom:10,
            background:"#F3F4F6", padding:"4px", borderRadius:10 }}>
            {PROJECTS.map(p=>(
              <button key={p.key} onClick={()=>setProject(p.key)}
                style={{ padding:"6px 14px", borderRadius:8,
                  border:`1px solid ${project===p.key?"#E5E7EB":"transparent"}`,
                  background:project===p.key?"#FFF":"transparent",
                  color:project===p.key?"#1A1A1A":"#6B7280",
                  cursor:"pointer", fontSize:11, fontWeight:700,
                  boxShadow:project===p.key?"0 1px 4px rgba(0,0,0,0.07)":"none",
                  fontFamily:"inherit", whiteSpace:"nowrap" }}>
                {p.label}
              </button>
            ))}
          </div>
          {/* Sections within project */}
          {(()=>{
            const sheetTasks = enriched.filter(t=>t.sheet===project);
            const sections   = [...new Set(sheetTasks.map(t=>t.section||""))];
            if(!sheetTasks.length) return (
              <div style={{ padding:40, textAlign:"center", color:"#9CA3AF", fontSize:13 }}>
                No tasks in this project.
              </div>
            );
            return sections.map(sec=>{
              const ts = sheetTasks.filter(t=>(t.section||"")===sec);
              return <SectionBlock key={sec} title={sec||project} tasks={ts}/>;
            });
          })()}
        </div>
      )}

      {/* ── ALL ── */}
      {tab==="all" && (
        <div>
          {[
            {label:"April 2026", pred:t=>t.month===3},
            {label:"May 2026",   pred:t=>t.month===4},
            {label:"No date",    pred:t=>t.month===null&&t.status!=="TARGET"},
          ].map(({label,pred})=>{
            const ts = enriched.filter(pred);
            if(!ts.length) return null;
            return <SectionBlock key={label} title={label} tasks={ts}/>;
          })}
        </div>
      )}
    </div>
  );
}


